<main class="main"><div class="main__inner"><div class="module-page">
<header class="module-page__header"><div><nav class="breadcrumb"><a href="<?=url('/admin/dashboard')?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Student Resources</span></nav><h1>Student Resources</h1><p>Publish files, notes or external links to all students, a class or one student.</p></div></header>
<form class="module-card" method="post" enctype="multipart/form-data" action="<?=url('/admin/notes')?>"><?=csrf_field()?><header class="module-card__header"><h2>Publish Resource</h2></header><div class="module-card__body"><div class="module-form-grid module-form-grid--three">
<div class="module-field"><label>Audience</label><select class="module-select" id="noteAudience" name="audience_type"><option value="all">All students</option><option value="class" selected>Specific class</option><option value="student">Specific student</option></select></div>
<fieldset class="module-field field--wide" data-note-class><legend>Select one or more classes</legend><div class="live-class-picker__options"><?php foreach($classes as$c):?><label class="live-class-picker__option"><input type="checkbox" name="class_ids[]" value="<?=$c['id']?>"><span><?=e($c['name'])?></span></label><?php endforeach?></div><small>Students in any selected class will receive this resource.</small></fieldset>
<div class="module-field" data-note-student hidden><label>Student</label><select class="module-select" name="student_id"><option value="">-- Select a student --</option><?php foreach($students as$s):?><option value="<?=$s['id']?>"><?=e($s['student_name'].' · '.$s['registration_no'].' · '.$s['class_name'])?></option><?php endforeach?></select></div>
<div class="module-field"><label>Subject <small>(optional)</small></label><select class="module-select" name="subject_id"><option value="">General resource</option><?php $seen=[];foreach($classes as$c):foreach($c['subjects']??[] as$s):if(isset($seen[$s['id']]))continue;$seen[$s['id']]=true;?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;endforeach?></select></div>
<div class="module-field"><label>Teacher</label><select class="module-select" name="teacher_id"><option value="">Admin</option><?php foreach($teachers as$t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach?></select></div>
<div class="module-field"><label>Title</label><input class="module-input" name="title" required maxlength="160"></div><div class="module-field"><label>Chapter / Topic</label><input class="module-input" name="chapter"></div><div class="module-field"><label>Publish date</label><input class="module-input" type="date" name="publish_date" value="<?=date('Y-m-d')?>" required></div>
<div class="module-field field--wide"><label>Description</label><textarea class="module-textarea" name="description"></textarea></div><div class="module-field"><label>Upload file</label><input class="module-input" type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx"></div><div class="module-field"><label>External link</label><input class="module-input" type="url" name="external_url" placeholder="https://example.com/resource"></div><div class="module-field"><label>Status</label><select class="module-select" name="status"><option value="published">Published</option><option value="draft">Draft</option></select></div>
</div></div><footer class="module-card__footer"><button class="btn btn--primary">Publish Resource</button></footer></form>
<section class="module-card"><header class="module-card__header"><h2>Resources</h2></header><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Date</th><th>Title</th><th>Audience</th><th>Subject</th><th>Resource</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($notes as$n):$audience=$n['audience_type']==='all'?'All students':($n['audience_type']==='student'?($n['student_name']??'Student'):($n['class_names']??$n['class_name']??'Class'));?><tr><td><?=e($n['publish_date'])?></td><td><strong><?=e($n['title'])?></strong><br><small><?=e($n['chapter']??'')?></small></td><td><?=e($audience)?></td><td><?=e($n['subject_name']??'General')?></td><td><?=!empty($n['attachment_path'])?'File ':''?><?=!empty($n['external_url'])?'Link':''?></td><td><span class="status-badge status-badge--<?=e($n['status'])?>"><?=e(ucfirst($n['status']))?></span></td><td><form method="post" action="<?=url('/admin/notes/'.$n['id'].'/delete')?>"><?=csrf_field()?><button class="class-action-button class-action-button--danger" aria-label="Delete resource"><i data-lucide="trash-2"></i></button></form></td></tr><?php endforeach?><?php if(!$notes):?><tr><td colspan="7"><div class="compact-empty"><h3>No resources yet</h3><p>Published resources will appear here.</p></div></td></tr><?php endif?></tbody></table></div></div></section>
</div></div></main>
<script>document.addEventListener('DOMContentLoaded',()=>{const a=document.getElementById('noteAudience'),c=document.querySelector('[data-note-class]'),s=document.querySelector('[data-note-student]');const sync=()=>{c.hidden=a.value!=='class';s.hidden=a.value!=='student';s.querySelector('select').required=a.value==='student'};a.addEventListener('change',sync);sync()});</script>
